#include "Session.hpp"
#include "WaveFile.hpp"
#include <iostream>
#include <fstream>
#include <chrono>
using namespace noir;using namespace noir::win;
int main(){int count=0;auto check=[&](bool ok,const char* name){if(!ok)throw std::runtime_error(name);std::cout<<"PASS "<<++count<<" "<<name<<'\n';};auto rejects=[&](auto fn,const char* name){bool fail=false;try{fn();}catch(...){fail=true;}check(fail,name);};auto folder=std::filesystem::temp_directory_path()/("NoirPortTests-"+std::to_string(std::chrono::steady_clock::now().time_since_epoch().count()));std::filesystem::create_directory(folder);try{
Session s;s.name="Studio \"two\" — test";s.channels[2].device="endpoint-{test}";s.channels[1].sends[3]=.5;s.clips[3]={"managed.wav","A name with spaces",.8f,.02f,true};auto restored=Session::parse(s.serialize());check(restored.serialize()==s.serialize(),"Session round trip preserves Unicode, routing and clips");
rejects([&]{Session::parse(s.serialize()+"junk");},"Session rejects trailing data");rejects([&]{Session::parse("NOIR_WINDOWS 2\n");},"Session rejects unknown version");rejects([&]{Session::parse(s.serialize().substr(0,150));},"Session rejects truncation");
auto bad=s;bad.channels[0].effect.p[Pitch]=NAN;rejects([&]{bad.validate();},"Session rejects NaN");bad=s;bad.channels[0].effect.order[1]=0;rejects([&]{bad.validate();},"Session rejects duplicate stages");bad=s;bad.clips[0].file="../private.wav";rejects([&]{bad.validate();},"Session rejects clip traversal");bad=s;bad.shortcuts[1]=bad.shortcuts[0];rejects([&]{bad.validate();},"Session rejects duplicate shortcuts");bad=s;bad.channels[0].pair=32;rejects([&]{bad.validate();},"Session rejects unavailable pair range");
auto core=std::make_unique<MixerCore>();s.apply(*core);check(core->channels[1].sends[3]==.5f,"Session applies independent bus sends");for(int p=0;p<7;++p){s.preset(p);s.validate();}check(true,"All seven presets validate");
for(int bits:{16,24,32}){SampleFormat f;f.floating=false;f.bits=f.validBits=bits;f.validate();std::array<uint8_t,16> bytes{};for(float v:{-1.f,-.5f,0.f,.25f,.999f}){f.write(bytes.data(),0,v);f.write(bytes.data(),1,-v);auto v2=f.stereo(bytes.data(),0);if(std::abs(v2.l-v)>1e-4||std::abs(v2.r-std::clamp(-v,-1.f,1.f))>1e-4)throw std::runtime_error("PCM round trip");}check(true,bits==16?"PCM16 conversion":bits==24?"PCM24 sign extension":"PCM32 conversion");}
SampleFormat f;f.floating=false;f.bits=32;f.validBits=24;std::array<uint8_t,16> b{};f.write(b.data(),0,.75f);check(b[0]==0&&std::abs(f.read(b.data(),0)-.75f)<1e-6,"24 valid bits in 32-bit container");f.channels=1;f.write(b.data(),0,-.25);auto mono=f.stereo(b.data(),0);check(mono.l==mono.r&&mono.l==-.25,"Mono input duplicates to stereo");rejects([&]{f.stereo(b.data(),1);},"Invalid channel pair rejected");f=SampleFormat{};float nan=NAN;memcpy(b.data(),&nan,4);check(f.read(b.data(),0)==0,"Capture sanitizes non-finite float");f.write(b.data(),0,2);check(f.read(b.data(),0)==1,"Output float clips to device range");f.channels=0;rejects([&]{f.validate();},"Invalid device format rejected");
std::array<Stereo,1024> samples{};for(size_t i=0;i<samples.size();++i)samples[i]={float(std::sin(i*.1)*.25),float(std::cos(i*.1)*.25)};auto wav=folder/"take.wav";{WaveFile out(wav);out.append(samples.data(),samples.size());out.finish();}std::ifstream input(wav,std::ios::binary);std::array<uint8_t,44> header{};input.read(reinterpret_cast<char*>(header.data()),44);input.close();check(read32(header.data()+40)==6144&&std::filesystem::file_size(wav)==6188,"PCM24 WAV final header matches frames");rejects([&]{WaveFile duplicate(wav);},"Recorder refuses to overwrite a take");
auto interrupted=folder/"interrupted.wav";{WaveFile partial(interrupted);partial.append(samples.data(),512);partial.checkpoint();}auto partial=folder/"interrupted.partial.wav";{std::ofstream trailing(partial,std::ios::binary|std::ios::app);trailing<<"x";}auto recovered=WaveFile::recover(partial);check(std::filesystem::file_size(recovered)==44+512*6&&!std::filesystem::exists(partial),"Recovery trims incomplete trailing PCM frame");
auto wrong=folder/"wrong.partial.wav";{std::ofstream out(wrong);out<<std::string(80,'x');}rejects([&]{WaveFile::recover(wrong);},"Recovery rejects other file formats");
Replay replay(10);for(int i=0;i<25;++i)replay.push({float(i),float(-i)});auto saved=replay.snapshot(5);check(saved.size()==10&&saved.front().l==15&&saved.back().l==24,"Replay retains chronological tail after wrap");replay.clear();check(replay.snapshot(30).empty(),"Changing record source can clear replay");
std::filesystem::remove_all(folder);std::cout<<count<<" tests passed\n";return 0;
}catch(const std::exception&e){std::cerr<<"FAIL "<<e.what()<<'\n';std::filesystem::remove_all(folder);return 1;}}
